using System;using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;using TMPro;using CatGunner.Runtime;
public static class ModeUiV2Refine {
 static bool Shape(Image i)=>i.sprite!=null&&(i.sprite.name.Contains("flat-ui-panel")||i.sprite.name.Contains("flat-ui-fill"));
 static void TextStyle(TMP_Text t,Color color,string key,float outline=0){t.color=color;string path="Assets/Game/PenguinModeUIV2/Refine-"+key+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(mat==null){mat=new Material(t.fontSharedMaterial);AssetDatabase.CreateAsset(mat,path);}mat.SetFloat("_OutlineWidth",outline);mat.SetColor("_OutlineColor",PenguinUiTheme.Navy);t.fontSharedMaterial=mat;var style=t.GetComponent<WeaponTextStyle>();if(style!=null&&style.Authored){var so=new SerializedObject(style);so.FindProperty("authoredMaterial").objectReferenceValue=mat;so.ApplyModifiedPropertiesWithoutUndo();Dirty(style);}Dirty(mat);Dirty(t);}
 static void Dirty(UnityEngine.Object o){EditorUtility.SetDirty(o);if(PrefabUtility.IsPartOfPrefabInstance(o))PrefabUtility.RecordPrefabInstancePropertyModifications(o);}
 public static object Main(){if(Application.dataPath!="/Volumes/ZHITAI_1T/IdleCatGunner/reconstruction/CatGunnerUnityClient/Assets"||Application.isPlaying)throw new Exception("Correct EditMode required");var c=UnityEngine.Object.FindAnyObjectByType<GameClient>(FindObjectsInactive.Include);var light=new Color32(227,241,248,255);var gold=new Color32(255,185,67,255);int cards=0,titles=0;
 foreach(var b in c.RaidMode.raidStart_ui.GetComponentsInChildren<Button>(true)){if(b.name.StartsWith("Gun_Slot")||b.name=="Helper_Slot"||b.name.StartsWith("Star")){var i=b.targetGraphic as Image;if(i!=null){i.color=light;Dirty(i);cards++;}}}
 foreach(var slot in c.RaidMode.raidStart_ui.GetComponentsInChildren<Raid_GunSlot>(true))foreach(var i in slot.UnSelected_obj.GetComponentsInChildren<Image>(true))if(Shape(i)){i.color=light;Dirty(i);cards++;}
 var helper=c.RaidMode.raidStart_ui.GetComponentInChildren<Raid_HelperSlot>(true);foreach(var i in helper.Locked_obj.GetComponentsInChildren<Image>(true)){if(Shape(i)&&i.transform!=helper.Locked_obj.transform)i.color=gold;else if(!Shape(i))i.color=Color.white;Dirty(i);}int refined=0;foreach(var t in helper.Locked_obj.GetComponentsInChildren<TMP_Text>(true))TextStyle(t,PenguinUiTheme.TextInk,"Unlock-"+refined++);
 var bossImage=c.BossMode.Start_UI.transform.Find("Panel/Image").GetComponent<Image>();bossImage.color=new Color32(24,53,76,255);Dirty(bossImage);
 foreach(var t in c.BossMode.Start_UI.transform.Find("Panel").GetComponentsInChildren<TMP_Text>(true))if(t.transform.parent==c.BossMode.Start_UI.transform.Find("Panel")||t==c.BossMode.Start_UI.Health_txt)TextStyle(t,Color.white,"Boss-"+refined++,.14f);
 var prism=c.Adventure.adventure_panel_ui.transform.Find("PrismCore_Panel/Panel");prism.GetComponent<Image>().color=new Color32(24,53,76,255);Dirty(prism.GetComponent<Image>());
 foreach(var t in prism.GetComponentsInChildren<TMP_Text>(true)){bool action=t.transform.parent!=prism;TextStyle(t,action?PenguinUiTheme.TextInk:Color.white,"Prism-"+refined++,action?0:.22f);}
 foreach(var draw in c.Slider.GetComponentInParent<Canvas>().GetComponentsInChildren<Draw_Relic_Btn>(true)){draw.ActionLabels=draw.GetComponentsInChildren<TextMeshProUGUI>(true).Where(t=>t!=draw.Price_txt).ToArray();draw.Color_Label_Able=PenguinUiTheme.TextInk;draw.Color_Label_Disable=Color.white;Dirty(draw);}
 foreach(var root in new GameObject[]{c.SpeedRun.Start_UI.gameObject,c.MineMode.mineStart_ui.gameObject,c.BossMode.Start_UI.gameObject,c.MonsterMode.monster_start_ui.gameObject})foreach(var t in root.GetComponentsInChildren<TMP_Text>(true)){
 if(t.transform.parent.name!="Reward"||!t.name.StartsWith("I2_txt"))continue;Undo.RecordObject(t,"Reward title above mixed background");t.color=Color.white;string path="Assets/Game/PenguinModeUIV2/RewardTitle-"+titles+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(mat==null){mat=new Material(t.fontSharedMaterial);AssetDatabase.CreateAsset(mat,path);}mat.SetFloat("_FaceDilate",0);mat.SetFloat("_OutlineWidth",.18f);mat.SetColor("_OutlineColor",PenguinUiTheme.Navy);t.fontSharedMaterial=mat;var style=t.GetComponent<WeaponTextStyle>();if(style!=null&&style.Authored){var so=new SerializedObject(style);so.FindProperty("authoredMaterial").objectReferenceValue=mat;so.ApplyModifiedPropertiesWithoutUndo();Dirty(style);}Dirty(mat);Dirty(t);titles++;}
 AssetDatabase.SaveAssets();var scene=c.gameObject.scene;EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Save failed");return new{cards,titles,saved=true};}
}
